package main

import (
	"errors"
	"net/http"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestRunExecutesCLIWithoutProfiles(t *testing.T) {
	t.Setenv("PPROF_ADDR", "")
	t.Setenv("CPUPROFILE", "")
	t.Setenv("TRACEFILE", "")
	t.Setenv("MEMPROFILE", "")

	executed := false
	listenCalled := false

	err := run(func() {
		executed = true
	}, func(addr string, handler http.Handler) error {
		listenCalled = true
		return nil
	})
	if err != nil {
		t.Fatalf("run() error = %v", err)
	}
	if !executed {
		t.Fatal("expected CLI callback to execute")
	}
	if listenCalled {
		t.Fatal("pprof listener should not be called when PPROF_ADDR is unset")
	}
}

func TestMaybeStartCPUProfile_CreatesFile(t *testing.T) {
	profilePath := filepath.Join(t.TempDir(), "cpu.prof")

	stop, err := maybeStartCPUProfile(profilePath)
	if err != nil {
		t.Fatalf("maybeStartCPUProfile() error = %v", err)
	}

	// Generate a little CPU activity before stopping the profile.
	var sink int
	for i := 0; i < 100_000; i++ {
		sink += i % 7
	}
	_ = sink

	stop()

	info, err := os.Stat(profilePath)
	if err != nil {
		t.Fatalf("stat profile file: %v", err)
	}
	if info.Size() == 0 {
		t.Fatal("expected CPU profile file to be non-empty")
	}
}

func TestMaybeStartTrace_CreatesFile(t *testing.T) {
	tracePath := filepath.Join(t.TempDir(), "trace.out")

	stop, err := maybeStartTrace(tracePath)
	if err != nil {
		t.Fatalf("maybeStartTrace() error = %v", err)
	}
	stop()

	info, err := os.Stat(tracePath)
	if err != nil {
		t.Fatalf("stat trace file: %v", err)
	}
	if info.Size() == 0 {
		t.Fatal("expected trace file to be non-empty")
	}
}

func TestMaybeWriteMemProfile_CreatesFile(t *testing.T) {
	memPath := filepath.Join(t.TempDir(), "mem.prof")

	if err := maybeWriteMemProfile(memPath); err != nil {
		t.Fatalf("maybeWriteMemProfile() error = %v", err)
	}

	info, err := os.Stat(memPath)
	if err != nil {
		t.Fatalf("stat memory profile file: %v", err)
	}
	if info.Size() == 0 {
		t.Fatal("expected memory profile file to be non-empty")
	}
}

func TestMaybeStartPprofServer_StartsListener(t *testing.T) {
	started := make(chan struct{}, 1)

	maybeStartPprofServer("127.0.0.1:9999", func(addr string, handler http.Handler) error {
		if addr != "127.0.0.1:9999" {
			t.Errorf("listener addr = %q, want %q", addr, "127.0.0.1:9999")
		}
		started <- struct{}{}
		return errors.New("stop")
	})

	select {
	case <-started:
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for pprof listener start")
	}
}

package auditcore

import (
	"slices"
	"testing"
)

func fixture() (Claim, Assessment, VerifySource) {
	c := Seal(Claim{FindingID: "f", RevisionID: "r", Title: "unsafe", File: "a.go", Start: 2, End: 2, Material: []Material{{"title", "unsafe"}}})
	e := Evidence{File: "a.go", Start: 2, End: 2, Quote: "sink(value)"}
	a := Assessment{FindingID: c.FindingID, RevisionID: c.RevisionID, Digest: c.Digest, CoveredMaterial: []Coverage{{"title", "unsafe"}}}
	for _, q := range Questions {
		a.Assertions = append(a.Assertions, Assertion{GuardState: "does_not_block", Kind: q, Status: "established", Statement: q, Reason: "source", Subject: "value", Consumer: "sink", Guard: "sink", ConsumerInput: "value", GuardInput: "value", Evidence: []Evidence{e}, ConsumerEvidence: []Evidence{e}, GuardEvidence: []Evidence{e}})
	}
	verify := func(x Evidence) (Evidence, bool) { return x, x == e }
	return c, a, verify
}
func TestEvidencePolicy(t *testing.T) {
	c, a, v := fixture()
	if got := Evaluate(c, a, v); got.Status != "confirmed" {
		t.Fatal(got)
	}
	a.Assertions[4].ConsumerEvidence = nil
	if got := Evaluate(c, a, v); got.Status != "unverified" || got.Crux == "" {
		t.Fatal(got)
	}
	a.Assertions[4].Status = "refuted"
	if got := Evaluate(c, a, v); got.Status != "unverified" {
		t.Fatal("unsupported impact suppressed weakness", got)
	}
	c, a, v = fixture()
	a.Assertions[3].Status = "refuted"
	a.Assertions[3].GuardState = "blocks"
	if got := Evaluate(c, a, v); got.Status != "rejected" {
		t.Fatal(got)
	}
	a.Assertions[3].GuardEvidence = []Evidence{{File: "other.go", Quote: "sink(value)"}}
	if got := Evaluate(c, a, v); got.Status != "unverified" {
		t.Fatal("unrelated guard rejected claim", got)
	}
	c, a, v = fixture()
	a.Digest = "swapped"
	if got := Evaluate(c, a, v); got.Status != "unverified" {
		t.Fatal(got)
	}
	c, a, v = fixture()
	a.Assertions[3].Assumptions = []Assumption{{Runtime: "parser", Behavior: "normalizes filenames"}}
	if got := Evaluate(c, a, v); got.Status != "unverified" {
		t.Fatal("unversioned assumption accepted", got)
	}
}
func TestSplitCoverage(t *testing.T) {
	c, _, v := fixture()
	e := Evidence{File: "a.go", Start: 2, End: 2, Quote: "sink(value)"}
	child := Child{Title: "narrow", Detail: "valid", File: "a.go", Start: 2, End: 2, Covers: []Coverage{{"title", "safe"}}, Evidence: []Evidence{e}}
	if _, err := ValidateChild(c, child, v); err != nil {
		t.Fatal(err)
	}
	if CompleteCoverage(c, []Child{child}) {
		t.Fatal("partial text counted as complete")
	}
	child.Covers[0].Quote = "unsafe"
	child.Detail = "unsafe"
	if !CompleteCoverage(c, []Child{child}) {
		t.Fatal("complete coverage missing")
	}
	child.Covers[0].Quote = "invented"
	if _, err := ValidateChild(c, child, v); err == nil {
		t.Fatal("invented claim accepted")
	}
}

func TestUnrelatedVerifiedQuotesCannotRefuteSubject(t *testing.T) {
	for _, kind := range []string{"attacker_control", "boundary"} {
		c, a, _ := fixture()
		for i := range a.Assertions {
			if a.Assertions[i].Kind == kind {
				a.Assertions[i].Status = "refuted"
				a.Assertions[i].Evidence = []Evidence{{File: "other.go", Start: 1, End: 1, Quote: "unrelated(value)"}}
			}
		}
		got := Evaluate(c, a, func(e Evidence) (Evidence, bool) { return e, true })
		if got.Status != "unverified" || !slices.Contains(got.Reasons, "insufficient_evidence:"+kind) {
			t.Fatalf("unrelated %s quote rejected claim", kind)
		}
	}
}

func TestMissingAnswerHasUnknownReason(t *testing.T) {
	c, a, v := fixture()
	missing := a.Assertions[len(a.Assertions)-1].Kind
	a.Assertions = a.Assertions[:len(a.Assertions)-1]
	got := Evaluate(c, a, v)
	for _, reason := range got.Reasons {
		if reason == "unknown:"+missing {
			return
		}
	}
	t.Fatalf("missing unknown reason for %s: %+v", missing, got)
}

func TestEstablishedUpstreamControlStillConfirms(t *testing.T) {
	c, a, _ := fixture()
	for i := range a.Assertions {
		if a.Assertions[i].Kind == "attacker_control" {
			a.Assertions[i].Evidence = []Evidence{{File: "handler.go", Start: 10, End: 10, Quote: "value := request.Query()"}}
		}
	}
	if got := Evaluate(c, a, func(e Evidence) (Evidence, bool) { return e, true }); got.Status != "confirmed" {
		t.Fatal(got)
	}
}
func TestAnchoredRefutationMustNameSubject(t *testing.T) {
	for _, kind := range []string{"attacker_control", "boundary"} {
		c, a, _ := fixture()
		for i := range a.Assertions {
			if a.Assertions[i].Kind == kind {
				a.Assertions[i].Status = "refuted"
				a.Assertions[i].Evidence = []Evidence{{File: "a.go", Start: 2, End: 2, Quote: "sink(other)"}}
			}
		}
		got := Evaluate(c, a, func(e Evidence) (Evidence, bool) { return e, true })
		if got.Status != "unverified" || !slices.Contains(got.Reasons, "insufficient_evidence:"+kind) {
			t.Fatal(got)
		}
	}
}

func TestEveryEstablishedAssertionMustQuoteItsSubject(t *testing.T) {
	for i, question := range Questions {
		t.Run(question, func(t *testing.T) {
			c, a, verify := fixture()
			a.Assertions[i].Subject = "unrelatedInput"
			got := Evaluate(c, a, verify)
			if got.Status != "unverified" || got.Assertions[i].Status != "unknown" {
				t.Fatal("unquoted subject was accepted", got)
			}
		})
	}
}

package cli

import (
	"strings"
	"testing"

	"github.com/block/codecrucible/internal/auditctx"
	"github.com/block/codecrucible/internal/chunk"
	"github.com/block/codecrucible/internal/ingest"
	"github.com/block/codecrucible/internal/sarif"
	"github.com/block/codecrucible/internal/sourceindex"
)

func TestCitedContextRetainsAdmittedEvidenceOnly(t *testing.T) {
	source := sourceindex.New(map[string]string{"routes/a.go": "one\ntwo\nthree", "other.go": "private"})
	text, _ := citedAuditContext(auditctx.NewRetriever(source), source, []auditClaim{{UnverifiedExploitSketch: "routes/a.go:2–3; absent.go:1; ../other.go:1"}}, map[string]bool{}, chunk.NewTokenCounter("", nil))
	if !strings.Contains(text, "2| two") || strings.Contains(text, "private") || strings.Contains(text, "absent.go") {
		t.Fatal(text)
	}
}

func TestRepeatedCitationsDoNotClaimMissingContext(t *testing.T) {
	source := sourceindex.New(map[string]string{"a.go": "one\ntwo\nthree\nfour\nfive\n"})
	text, _ := citedAuditContext(auditctx.NewRetriever(source), source, []auditClaim{{UnverifiedExploitSketch: "a.go:2 a.go:2 a.go:3"}}, nil, chunk.NewTokenCounter("", nil))
	if strings.Contains(text, "incomplete") || !strings.Contains(text, "3| three") {
		t.Fatal(text)
	}
}

func TestCitationsStillReportBudgetOmissions(t *testing.T) {
	source := sourceindex.New(map[string]string{"a.go": strings.Repeat("token ", 30000)})
	text, _ := citedAuditContext(auditctx.NewRetriever(source), source, []auditClaim{{UnverifiedExploitSketch: "a.go:1 a.go:1"}}, nil, chunk.NewTokenCounter("", nil))
	if !strings.Contains(text, "incomplete") {
		t.Fatal("missing budget warning")
	}
}

func TestIndexChunkAndValidationAgreeOnFinalNewline(t *testing.T) {
	for _, text := range []string{"one\ntwo", "one\ntwo\n"} {
		n := len(sourceindex.New(map[string]string{"a.go": text}).Lines("a.go"))
		chunks, err := chunk.NewChunker(chunk.NewTokenCounter("", nil), nil).Chunk(ingest.FlattenResult{FileMap: ingest.FileMap{"a.go": text}}, 10000, nil)
		if err != nil || len(chunks) != 1 || n != 2 {
			t.Fatalf("lines=%d chunks=%v err=%v", n, chunks, err)
		}
		if strings.Contains(chunks[0].XML, "3|") {
			t.Fatal("chunk emitted phantom line")
		}
		for _, line := range []int{n, n + 1} {
			doc := sarif.Build(sarif.AnalysisResult{SecurityIssues: []sarif.SecurityIssue{{Issue: "claim", FilePath: "a.go", StartLine: line}}}, nil, sarif.BuilderConfig{})
			doc = sarif.ValidateSourceLocations(doc, sarif.FileMap{"a.go": text})
			if (doc.Runs[0].Results[0].Locations[0].PhysicalLocation.Region != nil) != (line == n) {
				t.Fatal("validator/index disagreement")
			}
		}
	}
}

func TestChainedCitationsKeepPartialBudgetCoverage(t *testing.T) {
	source := sourceindex.New(map[string]string{"a.go": strings.Repeat(strings.Repeat("evidence ", 16)+"\n", 400)})
	text, kept := citedAuditContext(auditctx.NewRetriever(source), source, []auditClaim{{UnverifiedExploitSketch: "a.go:1-80 a.go:79-159 a.go:158-238 a.go:237-317"}}, nil, chunk.NewTokenCounter("", nil))
	if kept < 3 || !strings.Contains(text, "158|") || !strings.Contains(text, "incomplete") {
		t.Fatalf("kept %d ranges: %s", kept, text)
	}
}

func TestCitationsKeepClaimOrderUnderBudget(t *testing.T) {
	content := strings.Repeat(strings.Repeat("evidence ", 40)+"\n", 100)
	source := sourceindex.New(map[string]string{"a.go": content, "z.go": content})
	text, kept := citedAuditContext(auditctx.NewRetriever(source), source, []auditClaim{{UnverifiedExploitSketch: "z.go:1-80 a.go:1-80"}}, nil, chunk.NewTokenCounter("", nil))
	if kept != 1 || !strings.Contains(text, `path="z.go"`) || strings.Contains(text, `path="a.go"`) {
		t.Fatalf("citation priority changed: kept=%d %s", kept, text)
	}
}

