		if !ok || b.Specifier != tc.spec || !reflect.DeepEqual(b.Targets, tc.targets) {
			t.Errorf("ImportOf(%s, %s) = %+v, %v; want %s %v", tc.file, tc.name, b, ok, tc.spec, tc.targets)
