package sourceindex

import (
	"path"
	"sort"
	"strings"
)

// Import records the outcome of a local dependency lookup. An unresolved or
// ambiguous import is not evidence that the dependency or a guard is absent.
type Import struct {
	File      string   `json:"file"`
	Specifier string   `json:"specifier"`
	Status    string   `json:"status"` // resolved, unresolved, ambiguous, skipped
	Reason    string   `json:"reason,omitempty"`
	Targets   []string `json:"targets,omitempty"`
}

type importRequest struct {
	name       string
	exact      string // Prefer an existing literal path over inferred extensions.
	candidates []string
	many       bool
	skip       string
}

func vendored(p string) bool {
	for _, part := range strings.Split(p, "/") {
		switch part {
		case "vendor", "node_modules", "__pycache__", ".venv", "venv":
			return true
		}
	}
	return false
}

func (ix *Index) buildImports() {
	modules := map[string]string{}
	goDirs := map[string][]string{}
	kotlinNames := map[string][]string{}
	for _, p := range ix.paths {
		if vendored(p) {
			continue
		}
		if path.Base(p) == "go.mod" {
			if m := moduleLine.FindStringSubmatch(ix.files[p]); m != nil {
				modules[path.Dir(p)] = strings.Trim(m[1], "\"")
			}
		}
		if path.Ext(p) == ".go" {
			goDirs[path.Dir(p)] = append(goDirs[path.Dir(p)], p)
		}
		if ix.Language(p) == "kotlin" {
			for _, d := range ix.byFile[p] {
				name := d.Name
				if d.owner != "" {
					name = d.owner + "." + name
				}
				if pkg := ix.sources[p].packageName; pkg != "" {
					name = pkg + "." + name
				}
				kotlinNames[name] = appendUnique(kotlinNames[name], p)
			}
		}
	}
	for _, p := range ix.paths {
		if vendored(p) {
			continue
		}
		requests := ix.importRequests(p, modules, goDirs, kotlinNames)
		seen := map[string]bool{}
		for _, req := range requests {
			if seen[req.name] {
				continue
			}
			seen[req.name] = true
			imp := Import{File: p, Specifier: req.name, Status: "unresolved", Reason: "not_in_admitted_source"}
			if req.skip != "" {
				imp.Status, imp.Reason = "skipped", req.skip
			} else {
				vendor := false
				candidates := req.candidates
				if _, exists := ix.files[req.exact]; req.exact != "" && exists {
					candidates = []string{req.exact}
				}
				for _, candidate := range candidates {
					if vendored(candidate) {
						vendor = true
						continue
					}
					if candidate == p || candidate == ".." || strings.HasPrefix(candidate, "../") || path.IsAbs(candidate) {
						continue
					}
					if _, ok := ix.files[candidate]; ok {
						imp.Targets = appendUnique(imp.Targets, candidate)
					}
				}
				sort.Strings(imp.Targets)
				switch {
				case len(imp.Targets) > 1 && !req.many:
					imp.Status, imp.Reason = "ambiguous", "multiple_local_candidates"
				case len(imp.Targets) > 0:
					imp.Status, imp.Reason = "resolved", ""
				case vendor:
					imp.Status, imp.Reason = "skipped", "vendored_import"
				}
			}
			if imp.Status == "resolved" {
				for _, target := range imp.Targets {
					ix.graph[p] = appendUnique(ix.graph[p], target)
				}
			}
			ix.imports = append(ix.imports, imp)
			if ix.importsByFile[p] == nil {
				ix.importsByFile[p] = map[string]Import{}
			}
			ix.importsByFile[p][imp.Specifier] = imp
			ix.snapshot.Imports[imp.Status]++
		}
		sort.Strings(ix.graph[p])
	}
	sort.Slice(ix.imports, func(i, j int) bool {
		a, b := ix.imports[i], ix.imports[j]
		if a.File != b.File {
			return a.File < b.File
		}
		return a.Specifier < b.Specifier
	})
}

func appendUnique(values []string, s string) []string {
	for _, v := range values {
		if v == s {
			return values
		}
	}
	return append(values, s)
}

func (ix *Index) importRequests(file string, modules map[string]string, goDirs, kotlinNames map[string][]string) []importRequest {
	switch path.Ext(file) {
	case ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs":
		return javascriptImports(file, ix.files[file])
	case ".py":
		return pythonImports(file, ix.files[file])
	case ".go":
		return ix.goImports(file, modules, goDirs)
	case ".kt", ".kts":
		return ix.kotlinImports(file, kotlinNames)
	case ".c", ".cc", ".cpp", ".cxx", ".h", ".hpp":
		return cImports(file, ix.files[file])
	default:
		return nil
	}
}

package sourceindex

import (
	"path"
	"regexp"
)

var quotedInclude = regexp.MustCompile(`(?m)^\s*#\s*include\s*"([^"\n]+)"`)

func cImports(file, text string) []importRequest {
	dir := path.Dir(file)
	var out []importRequest
	for _, m := range quotedInclude.FindAllStringSubmatch(text, -1) {
		out = append(out, importRequest{name: m[1], candidates: []string{path.Join(dir, m[1]), path.Clean(m[1])}})
	}
	return out
}

package sourceindex

import (
	"path"
	"regexp"
	"sort"
	"strings"
)

var moduleLine = regexp.MustCompile(`(?m)^\s*module\s+([^\s]+)`)

func (ix *Index) goImports(file string, modules map[string]string, goDirs map[string][]string) []importRequest {
	var out []importRequest
	names := append([]string(nil), ix.sources[file].importPaths...)
	sort.Strings(names)
	for _, raw := range names {
		out = append(out, goImportRequest(raw, modules, goDirs))
	}

	return out
}
func goImportRequest(raw string, modules map[string]string, dirs map[string][]string) importRequest {
	req := importRequest{name: raw, many: true}
	best := ""
	roots := []string{}
	for dir, mod := range modules {
		if raw == mod || strings.HasPrefix(raw, mod+"/") {
			if len(mod) > len(best) {
				best = mod
				roots = nil
			}
			if mod == best {
				roots = append(roots, dir)
			}
		}
	}
	if best != "" {
		matchedRoots := 0
		for _, root := range roots {
			local := path.Join(root, strings.TrimPrefix(strings.TrimPrefix(raw, best), "/"))
			// A nested module is not part of its parent module's package tree.
			if owningGoModule(local, modules) != root || len(dirs[local]) == 0 {
				continue
			}
			matchedRoots++
			req.candidates = append(req.candidates, dirs[local]...)
		}
		if matchedRoots > 1 {
			req.many = false
		}
		return req
	}
	// Without a go.mod, accept only one matching repository directory.
	if len(modules) == 0 {
		var matches []string
		for dir := range dirs {
			if raw == dir || (dir != "." && strings.HasSuffix(raw, "/"+dir)) {
				matches = append(matches, dir)
			}
		}
		sort.Strings(matches)
		for _, dir := range matches {
			req.candidates = append(req.candidates, dirs[dir]...)
		}
		if len(matches) > 1 {
			req.many = false
		}
		return req
	}
	req.skip = "external_import"
	return req
}

func owningGoModule(dir string, modules map[string]string) string {
	best := ""
	for root := range modules {
		if root == "." || dir == root || strings.HasPrefix(dir, root+"/") {
			if best == "" || (root != "." && (best == "." || len(root) > len(best))) {
				best = root
			}
		}
	}
	return best
}

package sourceindex

import (
	"sort"
	"strings"
)

func (ix *Index) kotlinImports(file string, kotlinNames map[string][]string) []importRequest {
	var out []importRequest
	names := append([]string(nil), ix.sources[file].importPaths...)
	sort.Strings(names)
	for _, raw := range names {
		if strings.HasSuffix(raw, ".*") {
			out = append(out, importRequest{name: raw, skip: "unsupported_wildcard_import"})
			continue
		}
		out = append(out, importRequest{name: raw, candidates: kotlinNames[raw]})
	}
	return out
}

package sourceindex

import (
	"path"
	"regexp"
	"strings"
)

var jsAnyImport = regexp.MustCompile(`(?m)(?:\b(?:import|export)\s+[^\n;]*?\s+from\s*|\b(?:require|import)\s*\(\s*|\bimport\s*)['"]([^'"]+)['"]`)
var pyImport = regexp.MustCompile(`(?m)^\s*(?:from\s+([.\w]+)\s+import\s+([^\n#]+)|import\s+([\w.]+))`)

func javascriptImports(file, text string) []importRequest {
	dir := path.Dir(file)
	var out []importRequest
	for _, m := range jsAnyImport.FindAllStringSubmatch(text, -1) {
		raw := m[1]
		req := importRequest{name: raw}
		if strings.HasPrefix(raw, "./") || strings.HasPrefix(raw, "../") {
			req.exact = path.Join(dir, raw)
			req.candidates = resolveJSImport(dir, raw)
		} else {
			req.skip = "external_or_unsupported_import"
		}
		out = append(out, req)
	}
	return out
}
func pythonImports(file, text string) []importRequest {
	dir := path.Dir(file)
	var out []importRequest
	for _, m := range pyImport.FindAllStringSubmatch(text, -1) {
		raw := m[1]
		if raw == "" {
			raw = m[3]
		}
		base := "."
		rest := raw
		if strings.HasPrefix(raw, ".") {
			dots := len(raw) - len(strings.TrimLeft(raw, "."))
			base = dir
			for i := 1; i < dots; i++ {
				base = path.Dir(base)
			}
			rest = raw[dots:]
		}
		mod := path.Join(base, strings.ReplaceAll(rest, ".", "/"))
		candidates := []string{mod + ".py", path.Join(mod, "__init__.py")}
		// In "from . import helpers", helpers can be a sibling module.
		if rest == "" {
			candidates = []string{path.Join(base, "__init__.py")}
			for _, n := range strings.Split(m[2], ",") {
				n = strings.TrimSpace(strings.Split(n, " as ")[0])
				if regexpIdentifier(n) {
					child := path.Join(base, n)
					out = append(out, importRequest{name: raw + n, candidates: []string{child + ".py", path.Join(child, "__init__.py")}})
				}
			}
		}
		out = append(out, importRequest{name: raw, candidates: candidates})
	}
	return out
}
func regexpIdentifier(s string) bool {
	if s == "" {
		return false
	}
	for i, c := range s {
		if c != '_' && !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(i > 0 && c >= '0' && c <= '9') {
			return false
		}
	}
	return true
}

package main

import (
	"fmt"
	"log"
	"net/http"
	_ "net/http/pprof"
	"os"
	"runtime"
	"runtime/pprof"
	"runtime/trace"

	"github.com/block/codecrucible/internal/cli"
)

type listenAndServeFunc func(addr string, handler http.Handler) error

func main() {
	if err := run(cli.Execute, http.ListenAndServe); err != nil {
		log.Fatalf("codecrucible failed: %v", err)
	}
}

func run(executeCLI func(), listenAndServe listenAndServeFunc) error {
	maybeStartPprofServer(os.Getenv("PPROF_ADDR"), listenAndServe)

	stopCPUProfile, err := maybeStartCPUProfile(os.Getenv("CPUPROFILE"))
	if err != nil {
		return err
	}
	defer stopCPUProfile()

	stopTrace, err := maybeStartTrace(os.Getenv("TRACEFILE"))
	if err != nil {
		return err
	}
	defer stopTrace()

	executeCLI()

	return maybeWriteMemProfile(os.Getenv("MEMPROFILE"))
}

func maybeStartPprofServer(addr string, listenAndServe listenAndServeFunc) {
	if addr == "" || listenAndServe == nil {
		return
	}

	go func() {
		log.Printf("pprof listening on %s", addr)
		if err := listenAndServe(addr, nil); err != nil {
			log.Printf("pprof server stopped: %v", err)
		}
	}()
}

func maybeStartCPUProfile(cpuFile string) (func(), error) {
	if cpuFile == "" {
		return func() {}, nil
	}

	f, err := os.Create(cpuFile)
	if err != nil {
		return nil, fmt.Errorf("creating CPU profile: %w", err)
	}
	if err := pprof.StartCPUProfile(f); err != nil {
		_ = f.Close()
		return nil, fmt.Errorf("starting CPU profile: %w", err)
	}

	return func() {
		pprof.StopCPUProfile()
		_ = f.Close()
	}, nil
}

func maybeStartTrace(traceFile string) (func(), error) {
	if traceFile == "" {
		return func() {}, nil
	}

	f, err := os.Create(traceFile)
	if err != nil {
		return nil, fmt.Errorf("creating trace file: %w", err)
	}
	if err := trace.Start(f); err != nil {
		_ = f.Close()
		return nil, fmt.Errorf("starting trace: %w", err)
	}

	return func() {
		trace.Stop()
		_ = f.Close()
	}, nil
}

func maybeWriteMemProfile(memFile string) error {
	if memFile == "" {
		return nil
	}

	f, err := os.Create(memFile)
	if err != nil {
		return fmt.Errorf("creating memory profile: %w", err)
	}
	defer f.Close()

	runtime.GC()
	if err := pprof.WriteHeapProfile(f); err != nil {
		return fmt.Errorf("writing memory profile: %w", err)
	}
	return nil
}

package auditcore

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

const PolicyVersion = "audit-v3/1"

var Questions = []string{"attacker_control", "weakness", "boundary", "unmitigated", "impact"}

type Material struct {
	ID   string `json:"id"`
	Text string `json:"text"`
}
type Coverage struct {
	MaterialID string `json:"material_id"`
	Quote      string `json:"quote"`
}
type Claim struct {
	Evidence   []NamedEvidence `json:"evidence,omitempty"`
	FindingID  string          `json:"finding_id"`
	RevisionID string          `json:"revision_id"`
	Digest     string          `json:"claim_digest"`
	Title      string          `json:"title"`
	Detail     string          `json:"detail"`
	File       string          `json:"file"`
	Start      int             `json:"start_line"`
	End        int             `json:"end_line"`
	CWE        string          `json:"cwe"`
	Severity   float64         `json:"severity"`
	Material   []Material      `json:"material"`
}

func Seal(c Claim) Claim { c.Digest = ""; c.Digest = Digest(c); return c }

type FlowStep struct {
	From     string     `json:"from_expression"`
	To       string     `json:"to_expression"`
	Evidence []Evidence `json:"evidence"`
}

type Assertion struct {
	GuardState    string     `json:"guard_state"`
	ConsumerInput string     `json:"consumer_input_expression"`
	GuardInput    string     `json:"guard_input_expression"`
	Flow          []FlowStep `json:"flow"`
	Kind          string     `json:"kind"`
	Status        string     `json:"status"`
	Statement     string     `json:"statement"`
	Reason        string     `json:"reason"`
	// Subject identifies the concrete value/action. Consumer and Guard describe
	// its actual use and the decisive control; each has separate source anchors.
	Subject          string       `json:"subject_expression"`
	Consumer         string       `json:"consumer_expression"`
	Guard            string       `json:"guard_expression"`
	Evidence         []Evidence   `json:"evidence"`
	ConsumerEvidence []Evidence   `json:"consumer_evidence"`
	GuardEvidence    []Evidence   `json:"guard_evidence"`
	Assumptions      []Assumption `json:"assumptions"`
}
type Assumption struct {
	Runtime  string     `json:"runtime"`
	Version  string     `json:"version"`
	Behavior string     `json:"behavior"`
	Evidence []Evidence `json:"evidence"`
}
type Child struct {
	Title    string     `json:"title"`
	Detail   string     `json:"detail"`
	File     string     `json:"file"`
	Start    int        `json:"start_line"`
	End      int        `json:"end_line"`
	Covers   []Coverage `json:"covers"`
	Evidence []Evidence `json:"evidence"`
}

// ContextRequest asks for an admitted declaration or a bounded source range.
// It is evidence retrieval only, never permission to read other files or run code.
type ContextRequest struct {
	File   string `json:"file"`
	Symbol string `json:"symbol"`
	Start  int    `json:"start_line"`
	End    int    `json:"end_line"`
}
type Assessment struct {
	ContextRequests []ContextRequest `json:"context_requests"`
	CoveredMaterial []Coverage       `json:"covered_material"`
	FindingID       string           `json:"finding_id"`
	RevisionID      string           `json:"revision_id"`
	Digest          string           `json:"claim_digest"`
	Assertions      []Assertion      `json:"assertions"`
	Crux            string           `json:"crux"`
	Missing         []Evidence       `json:"missing_evidence"`
	Children        []Child          `json:"children"`
	Summary         string           `json:"summary"`
	Remediation     string           `json:"remediation"`
	RefinedSeverity float64          `json:"refined_severity"`
	SeverityBasis   string           `json:"severity_basis"`
	RefinedCWE      string           `json:"refined_cwe"`
}
type Outcome struct {
	Status     string      `json:"status"`
	Reasons    []string    `json:"reasons,omitempty"`
	Assertions []Assertion `json:"assertions"`
	Crux       string      `json:"crux,omitempty"`
	Policy     string      `json:"policy"`
}

// VerifySource is restricted to pinned, admitted source; callers additionally
// ensure that each cited range was actually present in the request bundle.
type VerifySource func(Evidence) (Evidence, bool)

func ValidIdentity(c Claim, a Assessment) bool {
	return c.FindingID == a.FindingID && c.RevisionID == a.RevisionID && c.Digest == a.Digest
}
func ValidShape(a Assessment) bool {
	seen := map[string]bool{}
	for _, v := range a.Assertions {
		if seen[v.Kind] || !question(v.Kind) || (v.Status != "established" && v.Status != "refuted" && v.Status != "unknown") {
			return false
		}
		seen[v.Kind] = true
	}
	return len(seen) == len(Questions)
}
func question(q string) bool {
	for _, v := range Questions {
		if v == q {
			return true
		}
	}
	return false
}
func checked(in []Evidence, verify VerifySource) []Evidence {
	var out []Evidence
	for _, e := range in {
		if v, ok := verify(e); ok {
			out = append(out, v)
		}
	}
	return out
}

// Evaluate conservatively binds claims and source evidence before computing a
// verdict. Semantic flow remains an attributed model assertion, never a graph fact.
func Evaluate(c Claim, a Assessment, verify VerifySource, assumptionVerifiers ...VerifySource) Outcome {
	verifyAssumption := verify
	if len(assumptionVerifiers) > 0 {
		verifyAssumption = assumptionVerifiers[0]
	}
	out := Outcome{Status: "unverified", Policy: PolicyVersion, Crux: strings.TrimSpace(a.Crux)}
	if !ValidIdentity(c, a) || !ValidShape(a) {
		out.Reasons = []string{"invalid_claim_assessment"}
		if ValidIdentity(c, a) {
			answered := map[string]bool{}
			for _, assertion := range a.Assertions {
				answered[assertion.Kind] = true
			}
			for _, q := range Questions {
				if !answered[q] {
					out.Reasons = append(out.Reasons, "unknown:"+q)
				}
			}
		}
		out.Crux = "A valid assessment bound to this claim revision is required."
		return out
	}
	states := map[string]string{}
	for _, v := range a.Assertions {
		v.Evidence = checked(v.Evidence, verify)
		v.ConsumerEvidence = checked(v.ConsumerEvidence, verify)
		v.GuardEvidence = checked(v.GuardEvidence, verify)
		for i := range v.Flow {
			v.Flow[i].Evidence = checked(v.Flow[i].Evidence, verify)
		}
		valid := strings.TrimSpace(v.Statement) != "" && strings.TrimSpace(v.Subject) != "" && strings.TrimSpace(v.Reason) != "" && len(v.Evidence) > 0
		if v.Kind == "attacker_control" || v.Kind == "boundary" {
			valid = valid && mentions(v.Evidence, v.Subject)
		}
		if v.Kind == "weakness" || ((v.Kind == "attacker_control" || v.Kind == "boundary") && v.Status == "refuted") {
			anchored := false
			for _, e := range v.Evidence {
				if claimAnchor(c, e) {
					anchored = true
					break
				}
			}
			valid = valid && anchored && mentions(v.Evidence, v.Subject)
		}
		if v.Kind == "impact" || v.Kind == "unmitigated" {
			valid = valid && mentions(v.Evidence, v.Subject) && len(v.ConsumerEvidence) > 0 && mentions(v.ConsumerEvidence, v.Consumer) && mentions(v.ConsumerEvidence, v.ConsumerInput) && follows(v.Subject, v.ConsumerInput, v.Flow)
			guardValid := false
			switch v.GuardState {
			case "blocks", "does_not_block":
				guardValid = len(v.GuardEvidence) > 0 && mentions(v.GuardEvidence, v.Guard) && mentions(v.GuardEvidence, v.GuardInput) && follows(v.Subject, v.GuardInput, v.Flow)
			case "not_found":
				// Absence is an attributed search result, backed by the actual
				// protection point. Never use it as a refutation.
				if v.Status == "established" {
					for _, e := range v.GuardEvidence {
						if claimAnchor(c, e) {
							guardValid = true
							break
						}
					}
				}
			}
			valid = valid && guardValid
			if v.Kind == "unmitigated" && ((v.Status == "refuted" && v.GuardState != "blocks") || (v.Status == "established" && v.GuardState == "blocks")) {
				valid = false
			}
		}
		for i := range v.Assumptions {
			x := &v.Assumptions[i]
			x.Evidence = checked(x.Evidence, verifyAssumption)
			if strings.TrimSpace(x.Runtime) == "" || strings.TrimSpace(x.Version) == "" || strings.TrimSpace(x.Behavior) == "" || len(x.Evidence) == 0 || !mentions(x.Evidence, x.Runtime) || !mentions(x.Evidence, x.Version) {
				valid = false
			}
		}
		if v.Status != "unknown" && !valid {
			out.Reasons = append(out.Reasons, "insufficient_evidence:"+v.Kind)
			v.Status = "unknown"
		}
		states[v.Kind] = v.Status
		out.Assertions = append(out.Assertions, v)
	}
	all := true
	for _, q := range Questions {
		if states[q] != "established" {
			all = false
		}
	}
	// Refuting an impact does not disprove the underlying weakness. Preserve
	// the broad claim unresolved; a separately supported narrower child can stand.
	for _, q := range []string{"attacker_control", "weakness", "boundary", "unmitigated"} {
		if states[q] == "refuted" {
			if !materialCovered(c.Material, a.CoveredMaterial) {
				out.Reasons = append(out.Reasons, "incomplete_claim_coverage")
				out.Crux = "Account for every original assertion before rejecting this claim."
				return out
			}
			out.Status = "rejected"
			out.Reasons = append(out.Reasons, "refuted:"+q)
			return out
		}
	}
	if all && !materialCovered(c.Material, a.CoveredMaterial) {
		out.Reasons = append(out.Reasons, "incomplete_claim_coverage")
		out.Crux = "Account for every original assertion before confirming this claim."
		return out
	}
	if all {
		out.Status = "confirmed"
		out.Crux = ""
		return out
	}
	for _, q := range Questions {
		if states[q] != "established" {
			state := states[q]
			if state == "" {
				state = "unknown"
			}
			out.Reasons = append(out.Reasons, state+":"+q)
		}
	}
	if out.Crux == "" {
		out.Crux = "Resolve the unsupported assertions: " + strings.Join(out.Reasons, ", ")
	}
	return out
}

// ValidateChild checks exact correspondence with the original, not an LLM's
// claim that a split is complete. Partial coverage keeps the parent visible.
func ValidateChild(parent Claim, c Child, verify VerifySource) (Child, error) {
	if strings.TrimSpace(c.Title) == "" || strings.TrimSpace(c.Detail) == "" || c.Start < 1 || c.End < c.Start {
		return c, fmt.Errorf("invalid child claim")
	}
	material := map[string]string{}
	for _, m := range parent.Material {
		material[m.ID] = m.Text
	}
	if len(c.Covers) == 0 {
		return c, fmt.Errorf("child has no original claim coverage")
	}
	for _, v := range c.Covers {
		if strings.TrimSpace(v.Quote) == "" || !strings.Contains(material[v.MaterialID], v.Quote) {
			return c, fmt.Errorf("child has invalid material coverage")
		}
	}
	c.Evidence = checked(c.Evidence, verify)
	anchored := false
	for _, e := range c.Evidence {
		if e.File == c.File && e.Start <= c.End && e.End >= c.Start {
			anchored = true
		}
	}
	if !anchored {
		return c, fmt.Errorf("child has no verified primary anchor")
	}
	return c, nil
}
func CompleteCoverage(parent Claim, children []Child) bool {
	if len(children) == 0 {
		return false
	}
	for _, m := range parent.Material {
		text := strings.TrimSpace(m.Text)
		if text == "" {
			continue
		}
		covered := make([]bool, len(text))
		for _, c := range children {
			for _, v := range c.Covers {
				if v.MaterialID != m.ID || strings.TrimSpace(v.Quote) == "" {
					continue
				}
				// A covered assertion must also remain explicit in the visible child.
				if !strings.Contains(c.Title, v.Quote) && !strings.Contains(c.Detail, v.Quote) {
					continue
				}
				at := strings.Index(text, v.Quote)
				if at < 0 {
					continue
				}
				for i := at; i < at+len(v.Quote); i++ {
					covered[i] = true
				}
			}
		}
		for i, ch := range []byte(text) {
			if !covered[i] && ch != ' ' && ch != '\n' && ch != '\r' && ch != '\t' {
				return false
			}
		}
	}
	return true
}

// Source expressions must occur in their evidence; explicit, quote-backed flow
// steps connect renamed values. This checks correspondence, not exploitability.
func mentions(evidence []Evidence, expression string) bool {
	expression = strings.Join(strings.Fields(expression), " ")
	if expression == "" {
		return false
	}
	for _, e := range evidence {
		text := strings.Join(strings.Fields(e.Quote), " ")
		for offset := 0; offset < len(text); {
			at := strings.Index(text[offset:], expression)
			if at < 0 {
				break
			}
			at += offset
			end := at + len(expression)
			first, _ := utf8.DecodeRuneInString(expression)
			last, _ := utf8.DecodeLastRuneInString(expression)
			before, after := rune(0), rune(0)
			if at > 0 {
				before, _ = utf8.DecodeLastRuneInString(text[:at])
			}
			if end < len(text) {
				after, _ = utf8.DecodeRuneInString(text[end:])
			}
			ident := func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' || r == '$' }
			if (!ident(first) || !ident(before)) && (!ident(last) || !ident(after)) {
				return true
			}
			offset = at + 1
		}
	}
	return false
}
func follows(from, to string, steps []FlowStep) bool {
	if from == "" || to == "" {
		return false
	}
	seen := map[string]bool{from: true}
	for i := 0; i <= len(steps); i++ {
		if seen[to] {
			return true
		}
		changed := false
		for _, s := range steps {
			if seen[s.From] && !seen[s.To] && mentions(s.Evidence, s.From) && mentions(s.Evidence, s.To) {
				seen[s.To] = true
				changed = true
			}
		}
		if !changed {
			return false
		}
	}
	return false
}

func materialCovered(material []Material, coverage []Coverage) bool {
	for _, m := range material {
		if strings.TrimSpace(m.Text) == "" {
			continue
		}
		ok := false
		for _, c := range coverage {
			if c.MaterialID == m.ID && strings.TrimSpace(c.Quote) == strings.TrimSpace(m.Text) {
				ok = true
				break
			}
		}
		if !ok {
			return false
		}
	}
	return true
}

func claimAnchor(c Claim, e Evidence) bool {
	matches := func(file string, start, end int) bool {
		return file != "" && file == e.File && start > 0 && e.Start <= max(start, end) && e.End >= start
	}
	if matches(c.File, c.Start, c.End) {
		return true
	}
	for _, a := range c.Evidence {
		if matches(a.Evidence.File, a.Evidence.Start, a.Evidence.End) {
			return true
		}
	}
	return false
}

package auditctx

import (
	"fmt"
	"strings"
	"testing"
)

func goRepo() map[string]string {
	return map[string]string{
		"internal/handlers/pages.go": `package handlers; import "example/internal/models"

var searchTmpl *texttmpl.Template

func Load(dir string) {
	searchTmpl, _ = texttmpl.ParseFiles(filepath.Join(dir, "search.html"))
}

func (a *App) PageSearch(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query().Get("q")
	docs := a.DB.SearchDocuments(q)
	var u models.User
	_ = searchTmpl.Execute(w, map[string]any{"Query": q, "Results": docs, "User": u})
}
`,
		"main.go": `package main

func routes(a *handlers.App) {
	r := chi.NewRouter()
	r.Group(func(r chi.Router) {
		r.Use(auth.RequireAuth)
		r.Get("/search", a.PageSearch)
	})
}
`,
		"internal/db/queries.go": `package db

func (d *DB) SearchDocuments(q string) []Document {
	rows := d.Query("SELECT * FROM docs WHERE title LIKE '%" + q + "%'")
	return scan(rows)
}

func scan(rows *Rows) []Document { return nil }
`,
		"internal/models/models.go": `package models

type User struct {
	ID   int64
	Role string ` + "`json:\"role\"`" + `
}
`,
		"web/templates/search.html": "<h1>Results for {{.Query}}</h1>\n",
	}
}

func TestRetrieveFindsCallersTemplatesAndDefinitions(t *testing.T) {
	ix := NewIndex(goRepo())
	got := ix.Retrieve(Claim{File: "internal/handlers/pages.go", Start: 13, End: 13}, map[string]bool{"internal/handlers/pages.go": true})
	want := []string{
		"main.go:1-9 reference to PageSearch",
		"web/templates/search.html:1-1 template search.html",
		"internal/db/queries.go:3-6 definition of SearchDocuments",
		"internal/models/models.go:3-6 type User",
	}
	var have []string
	for _, e := range got {
		if e.File == "" {
			continue
		}
		have = append(have, fmt.Sprintf("%s:%d-%d %s", e.File, e.Start, e.End, e.Reason))
	}
	if strings.Join(have, "\n") != strings.Join(want, "\n") {
		t.Fatalf("Retrieve =\n%s\nwant\n%s", strings.Join(have, "\n"), strings.Join(want, "\n"))
	}

	skipped := ix.Retrieve(Claim{File: "internal/handlers/pages.go", Start: 13, End: 13}, map[string]bool{"main.go": true, "web/templates/search.html": true})
	for _, e := range skipped {
		if e.File == "main.go" || e.File == "web/templates/search.html" {
			t.Errorf("retrieved a file already sent: %+v", e)
		}
	}
}

func TestRetrieveSkipsCommonNames(t *testing.T) {
	files := map[string]string{"a.go": "package a\n\nfunc handler() {\n\tsink()\n}\n"}
	for i := 0; i < maxCallerSpan+1; i++ {
		files[fmt.Sprintf("u%d.go", i)] = "package u\n\nvar _ = handler\nvar _ = Sink2\n"
	}
	files["a.go"] = "package a\n\nfunc handler() {\n\tSink2()\n}\n"
	files["b.go"] = "package a\n\nfunc Sink2() {}\n"
	ix := NewIndex(files)
	for _, e := range ix.Retrieve(Claim{File: "a.go", Start: 4}, nil) {
		if strings.HasPrefix(e.Reason, "reference to") {
			t.Errorf("generic caller retrieved: %+v", e)
		}
	}
	// Sink2 is referenced from too many files to retrieve its callers, but
	// its single definition is still retrieved as a callee.
	files["a.go"] = "package a\n\nfunc Caller() {\n\tSink2()\n}\n"
	ix = NewIndex(files)
	got := ix.Retrieve(Claim{File: "a.go", Start: 4}, nil)
	if len(got) != 1 || got[0].Reason != "definition of Sink2" {
		t.Errorf("Retrieve = %+v", got)
	}
}

func TestRenderMergesRangesWithinBudget(t *testing.T) {
	ix := NewIndex(map[string]string{"a.go": "l1\nl2\nl3\nl4\nl5\nl6\nl7\nl8\nl9\n", "b.go": strings.Repeat("x\n", 50)})
	count := func(s string) int { return len(s) }
	out, kept := Render(ix, []Excerpt{
		{File: "a.go", Start: 2, End: 3},
		{File: "a.go", Start: 3, End: 4},
		{File: "a.go", Start: 7, End: 8},
		{File: "a.go", Start: 2, End: 2}, // already covered
		{File: "b.go", Start: 1, End: 50},
	}, 60, count)
	want := "<file path=\"a.go\" lines=\"2-4,7-8\">\n2| l2\n3| l3\n4| l4\n...\n7| l7\n8| l8\n</file>\n\nAudit context omitted: token budget exhausted\n"
	// Three admitted excerpts plus the contained excerpt are all covered.
	if out != want || kept != 4 {
		t.Fatalf("Render = %q (kept %d); want %q", out, kept, want)
	}
}

// kotlinRepo models a handler whose client-supplied amount is validated two
// calls away: the Transfer constructor passes it to PaymentLimits.requireValid.
func kotlinRepo() map[string]string {
	return map[string]string{
		"app/src/main/kotlin/pay/RequestTransferAction.kt": `package pay

class RequestTransferAction(private val accounts: AccountClient) {
  fun handle(req: TransferRequest): TransferResponse {
    val transfer = buildTransfer(req)
    return TransferResponse(transfer.id)
  }

  private fun buildTransfer(req: TransferRequest): Transfer =
    Transfer(
      id = req.idempotencyKey,
      direction = Direction.OUTBOUND,
      account = accounts.lookUp(req.accountToken),
      amount = Money.of(req.currencyCode, req.amount),
      memo = req.memo,
    )
}
`,
