func TestCallerDefinitionLimitIsReported(t *testing.T) {
	var guards, names []string
	files := map[string]string{"handler.ts": "export function profileHandler(req,res) {\n return res.json(req.body);\n}\n"}
	for i := 0; i < maxCallerDefinitions+2; i++ {
		name := fmt.Sprintf("guard%c", 'A'+i)
		names = append(names, name)
		files[name+".ts"] = fmt.Sprintf("export function %s(req,res,next) {\n next();\n}\n", name)
		guards = append(guards, "import { "+name+" } from './"+name+"';")
	}
