	got := retrievedText(files, "handler.ts", 2)
	if n := strings.Count(got, "export function guard"); n != maxCallerDefinitions {
		t.Fatalf("retrieved %d guard definitions, want %d: %s", n, maxCallerDefinitions, got)
	}
	if !strings.Contains(got, "Audit context omitted: caller definition limit reached") {
		t.Fatal(got)
	}
}

func TestRetrieverSharesSourceSnapshot(t *testing.T) {
	// Retrieval must read the facts the scan already extracted. A retriever
	// over a prebuilt snapshot sees exactly what a self-built one sees, and
	// never anything outside that snapshot.
	files := map[string]string{
		"handlers.ts": "export function listRecords(req, res) {\n return res.json(load(req.body.owner));\n}\n",
		"router.ts":   "import { bindOwner } from './identity';\nrouter.get('/records', bindOwner, listRecords);\n",
		"identity.ts": "export function bindOwner(req, res, next) {\n req.body.owner = req.auth.id;\n next();\n}\n",
		"outside.ts":  "router.get('/other', OUTSIDE_SNAPSHOT_GUARD, listRecords);\n",
	}
	admitted := map[string]string{"handlers.ts": files["handlers.ts"], "router.ts": files["router.ts"], "identity.ts": files["identity.ts"]}
	snapshot := sourceindex.New(admitted)
	shared := NewRetriever(snapshot)
	claim := Claim{File: "handlers.ts", Start: 2, End: 2}
	count := func(s string) int { return len(s) }
	got, _ := Render(shared, shared.Retrieve(claim, nil), 100000, count)
	own := NewIndex(admitted)
	want, _ := Render(own, own.Retrieve(claim, nil), 100000, count)
	if got != want || !strings.Contains(got, "req.body.owner = req.auth.id") || strings.Contains(got, "OUTSIDE_SNAPSHOT_GUARD") {
		t.Fatalf("shared retrieval differs from self-built or left the snapshot:\n%s\n---\n%s", got, want)
	}
}

